#!/usr/bin/env bash
# L2 evidence: attention RTL bit-exact check under the TRAINING-FROZEN calibration.
#
# Builds a Verilator TB from the in-repo read-only attention RTL copy
# (graduate/rtl/encoder/third_party/attn_single_head.sv) plus the attn_params.svh
# regenerated by the frozen model, then runs it for every validation sample.
# The TB only loads inputs/params, waits for done, reads memories back and
# compares bit for bit; it performs no arithmetic itself.
#
#   bash graduate/ds_tasks/attn_scale/rtl_check.sh
set -euo pipefail
here="$(cd "$(dirname "$0")" && pwd)"
root="$(cd "$here/../../.." && pwd)"
build="${BUILD_DIR:-/tmp/opencode/attn_scale/rtl_check}"
logs="$here/logs"
mkdir -p "$build/rtl" "$build/vectors" "$logs"

rtl="$root/graduate/rtl/encoder/third_party/attn_single_head.sv"
params="$root/graduate/encoder/rtl/attn_params.svh"   # regenerated (gitignored)
model="$root/graduate/encoder/model/attn_int_model.py"
vec="$root/graduate/encoder/vectors"

cp "$rtl" "$build/rtl/"
cp "$here/tb/tb_attn.cpp" "$build/tb_attn.cpp"

echo "== verilator build =="
verilator --cc --exe --build -j 4 -O2 -Wno-fatal --top-module attn_single_head \
    -I"$build/rtl" "$build/rtl/attn_single_head.sv" "$build/tb_attn.cpp" \
    --Mdir "$build/obj_dir" -o tb_attn > "$logs/rtl_build.log" 2>&1
echo "RTL_BUILD_EXIT=$?"

rc=0
for S in 0 1 2; do
    python3 "$model" --sample "$S" > "$logs/model_sample$S.log" 2>&1 || rc=1
    cp "$params" "$build/rtl/attn_params.svh"
    cp "$vec"/*.txt "$build/vectors/"
    cp "$vec/params.json" "$build/vectors/"
    if "$build/obj_dir/tb_attn" "$build/vectors" > "$logs/rtl_val_sample$S.log" 2>&1; then
        st=0
    else
        st=1
        rc=1
    fi
    sample=$(grep -o '"input_file": *"[^"]*"' "$logs/model_sample$S.log" | cut -d'"' -f4)
    summary=$(grep -E 'bit-exact total|FP32 NRMSE|RESULT' "$logs/rtl_val_sample$S.log" | tr '\n' ' ')
    echo "sample$S ($sample) exit=$st  $summary"
done
echo "RTL_CHECK_EXIT=$rc"
exit $rc
